-- Arbeitsrecht Berufsbildung > Betriebswirtschaftliche Grundlagen > Finanzierungsarten > Leasing
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Bleibt der Leasinggeber bei einem Leasingvertrag für IT-Hardware der Eigentümer?', 2, '[{"text": "Ja", "correct": true, "because": "Beim Leasing bleibt das Eigentum beim Leasinggeber"}, {"text": "Nein", "correct": false, "because": "Eigentum wird nicht übertragen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind beim Leasing von Softwarelizenzen für einen IT-Betrieb monatliche Zahlungen erforderlich?', 2, '[{"text": "Ja", "correct": true, "because": "Leasing bedeutet regelmäßige Raten"}, {"text": "Nein", "correct": false, "because": "Monatliche Zahlungen sind üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch Leasing von Servern hohe Anfangsinvestitionen vermeiden?', 2, '[{"text": "Ja", "correct": true, "because": "Leasing verteilt Kosten über die Laufzeit"}, {"text": "Nein", "correct": false, "because": "Leasing reduziert Anfangskosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist beim Leasing von IT-Ausrüstung eine Abschreibung durch den Betrieb möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Das Eigentum liegt beim Leasinggeber"}, {"text": "Ja", "correct": false, "because": "Abschreibung nur beim Eigentümer"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb beim Leasing von Hardware die Ausrüstung am Vertragsende kaufen?', 2, '[{"text": "Ja", "correct": true, "because": "Viele Leasingverträge bieten Kaufoptionen"}, {"text": "Nein", "correct": false, "because": "Kaufoption ist oft möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein wesentliches Merkmal der Finanzierungsart Leasing für einen IT-Betrieb?', 2, '[{"text": "Nutzung ohne Eigentum", "correct": true, "because": "Leasing bedeutet Nutzung, nicht Besitz"}, {"text": "Sofortige Eigentumsübertragung", "correct": false, "because": "Das gilt für Kauf"}, {"text": "Keine Zahlungen erforderlich", "correct": false, "because": "Leasing erfordert Raten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten entstehen einem IT-Betrieb typischerweise beim Leasing von Servern?', 3, '[{"text": "Monatliche Leasingraten", "correct": true, "because": "Leasing bedeutet regelmäßige Zahlungen"}, {"text": "Einmalige Anschaffungskosten", "correct": false, "because": "Das gilt für Kauf"}, {"text": "Nur Wartungskosten", "correct": false, "because": "Raten sind primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich für einen IT-Betrieb durch das Leasing von Software?', 3, '[{"text": "Geringere Anfangskosten", "correct": true, "because": "Leasing verteilt Kosten über die Zeit"}, {"text": "Langfristige Kostenersparnis", "correct": false, "because": "Kauf ist langfristig günstiger"}, {"text": "Keine Wartung erforderlich", "correct": false, "because": "Wartung bleibt notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Finanzierungsquelle wird beim Leasing von IT-Ausrüstung häufig genutzt?', 2, '[{"text": "Fremdkapital", "correct": true, "because": "Leasing ist eine Form der Fremdfinanzierung"}, {"text": "Eigenkapital", "correct": false, "because": "Weniger üblich beim Leasing"}, {"text": "Kaufvertrag", "correct": false, "because": "Das ist eine andere Finanzierungsart"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nachteil des Leasings von Hardware für einen IT-Betrieb?', 3, '[{"text": "Keine Eigentumsübertragung", "correct": true, "because": "Eigentum bleibt beim Leasinggeber"}, {"text": "Hohe Anfangsinvestition", "correct": false, "because": "Das gilt für Kauf"}, {"text": "Keine Flexibilität", "correct": false, "because": "Leasing bietet oft Flexibilität"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Finanzierungsart Leasing für einen IT-Betrieb?', 4, '[{"text": "Nutzung ohne Eigentum", "correct": true, "because": "Eigentum bleibt beim Leasinggeber"}, {"text": "Monatliche Zahlungen", "correct": true, "because": "Leasing erfordert Raten"}, {"text": "Hohe Anfangskosten", "correct": false, "because": "Leasing reduziert Anfangskosten"}, {"text": "Flexibilität bei Vertragsende", "correct": true, "because": "Optionen wie Rückgabe oder Kauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Leasing von IT-Ausrüstung für einen IT-Betrieb?', 3, '[{"text": "Geringere Anfangskosten", "correct": true, "because": "Kosten werden verteilt"}, {"text": "Flexibilität bei Technologie-Upgrades", "correct": true, "because": "Leasing erlaubt Austausch"}, {"text": "Sofortiges Eigentum", "correct": false, "because": "Eigentum bleibt beim Leasinggeber"}, {"text": "Liquiditätsschonung", "correct": true, "because": "Kein Kapital gebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat das Leasing von Hardware für einen IT-Betrieb?', 4, '[{"text": "Keine Eigentumsübertragung", "correct": true, "because": "Eigentum bleibt beim Leasinggeber"}, {"text": "Langfristig höhere Kosten", "correct": true, "because": "Raten können Kauf übersteigen"}, {"text": "Hohe Anfangsinvestition", "correct": false, "because": "Das gilt für Kauf"}, {"text": "Vertragsbindung", "correct": true, "because": "Leasingverträge sind oft langfristig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten entstehen beim Leasing von Software für einen IT-Betrieb?', 3, '[{"text": "Monatliche Leasingraten", "correct": true, "because": "Leasing bedeutet regelmäßige Zahlungen"}, {"text": "Wartungskosten", "correct": true, "because": "Wartung kann zusätzlich anfallen"}, {"text": "Einmalige Anschaffungskosten", "correct": false, "because": "Das gilt für Kauf"}, {"text": "Kosten für Vertragsverlängerung", "correct": true, "because": "Option bei Leasingverträgen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet Leasing vom Kauf für einen IT-Betrieb?', 3, '[{"text": "Eigentum bleibt beim Leasinggeber", "correct": true, "because": "Leasing überträgt kein Eigentum"}, {"text": "Laufende Zahlungen statt Einmalzahlung", "correct": true, "because": "Leasing hat Raten"}, {"text": "Geringere Gesamtkosten", "correct": false, "because": "Leasing kann teurer sein"}, {"text": "Keine Abschreibung beim Leasingnehmer", "correct": true, "because": "Eigentum nicht beim Betrieb"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Beim Leasing von Hardware bleibt das Eigentum beim Leasinggeber. b) Leasing erfordert hohe Anfangskosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eigentum ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Leasing von Software hat monatliche Raten. b) Leasing reduziert Anfangskosten.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Raten und geringere Anfangskosten"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Beim Leasing von Servern gibt es keine Abschreibungen für den Betrieb. b) Leasing ist immer günstiger als Kauf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Abschreibungen, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Leasing bietet Flexibilität bei Technologie-Upgrades. b) Leasing führt zu sofortigem Eigentum.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Leasing bindet weniger Kapital als Kauf. b) Leasing hat langfristig geringere Kosten als Kauf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Weniger Kapitalbindung, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');